// Golden values reproduced from the prototype's own logic (design lines 3096–5239 run in node:vm, renderValsEN:
// src/features/quality/quality.golden.json, generated by scripts/proto-golden-quality.ts). The domain reads the NCRs as
// Vigie reports them — here the prototype HLT_NCRS materialised by the Vigie mirror's seed snapshot
// (prototypeNcrSnapshot), the same records the database mirror holds — and the deliverables as the seed writes them
// (HLT_DELIVS, D-110… on the other projects, year-less due dates read forward). Progress recorded in Keystone (pending
// sync with Vigie), the viewer rules and the post-action states are asserted on top.
import { describe, expect, it } from 'vitest';
import { DEMO_TODAY_ISO } from '@/domain/clock';
import PROTO from '@/server/prototype/prototype-data.json';
import GEN from '@/server/prototype/prototype-generated.json';
import { deliverableStatus, NCR_FLOW, ncrStatus, type DeliverableStatus } from '@/server/db/codes';
import { forwardIso } from '@/server/db/seed/dates';
import { prototypeNcrSnapshot, type ProtoNcrRow } from '@/server/integrations/vigie/prototype-snapshot';
import GOLD from '@/features/quality/quality.golden.json';
import { money } from '@/lib/format';
import {
  QUALITY_COLOR, RACI_LABEL, RACI_ORDER, awaitsVerification, deliverableAcceptanceItems, deliverableActionFor, deliverableChips, deliverableFilterOf,
  deliverableHint, deliverableKpis, deliverableSteps, deliverableTagOf, depositTypeOf, ncrActionFor, ncrChips, ncrFilterOf, ncrKpis, ncrOverdueAsOf, ncrRequestText, ncrSegments,
  ncrStatusTagOf, ncrSteps, ncrSyncLine, ncrSyncStateOf, ncrVerificationItems, producerNextOf, qualityBadge, qualityTabOf, severityTagOf,
  type DeliverableLike, type NcrLike, type NcrProgressLike, type QualityKpi,
} from './quality';

/* eslint-disable @typescript-eslint/no-explicit-any */
const P = PROTO as any;
const G = (GOLD as any).en;
const DATA = ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012'];

const NCRS: (NcrLike & { projectCode: string; vigieUrl: string })[] = prototypeNcrSnapshot(P.HLT_NCRS as ProtoNcrRow[], DATA).map((r) => ({
  ...r, requestedStatus: null, pendingProgress: [], vigieUrl: `vigie:${r.number}`,
}));
const ncrsOf = (code: string) => NCRS.filter((n) => n.projectCode === code);

const pmOf = new Map(((GEN as any).initialProjects as { code: string; pm: string }[]).map((p) => [p.code, p.pm]));
/** Deliverables as the seed writes them (seed/quality.ts protoDeliverables + acceptanceOf); `acc` is the prototype text. */
function deliverablesOf(code: string): DeliverableLike[] {
  const base = P.HLT_DELIVS as { id: string; title: string; type: string; due: string; status: string; acc: string; raci: Record<string, string> }[];
  const rows: typeof base = code === 'HLT-026' ? base : base.slice(0, 4).map((d, i) => ({ ...d, id: 'D-1' + (10 + i), raci: { ...d.raci, R: pmOf.get(code)! } }));
  return rows.map((d) => {
    const status = deliverableStatus.code(d.status);
    return {
      number: d.id, title: d.title, status, dueOn: forwardIso(d.due, status === 'accepted' || status === 'rejected'), typeLabel: d.type, acceptanceText: d.acc,
      raci: RACI_ORDER.map((role) => ({ role, name: d.raci[role] ?? null })),
    };
  });
}

const kpiOut = (k: QualityKpi) => ({ label: k.label, value: k.money ? money(k.value, 'en') : String(k.value), sub: k.sub, color: k.lo ? QUALITY_COLOR.lo : QUALITY_COLOR.text });
const EDITOR = { role: 'director', canEdit: true };

describe('NCR log (Vigie NCRs) — ncrKpis / ncrChips / ncrRows / ncrVals', () => {
  it.each(DATA)('%s: KPI tiles (Overdue actions as of the next weekly review: the prototype’s count)', (code) => {
    // R-013: the as-of date follows the business date (+ 7 days); at the prototype's status date it is its 2 Oct.
    expect(ncrOverdueAsOf(DEMO_TODAY_ISO)).toBe('2026-10-02');
    expect(ncrKpis(ncrsOf(code), DEMO_TODAY_ISO, DEMO_TODAY_ISO).map(kpiOut)).toEqual(G.projects[code].ncr.kpis);
  });

  it.each(DATA)('%s: severity chips, tags, progress segments and next step of every row', (code) => {
    const ncrs = ncrsOf(code);
    expect(ncrChips(ncrs).map((c) => ({ label: c.label, count: c.count }))).toEqual(G.projects[code].ncr.chips);
    expect(ncrs.map((n) => ({
      id: n.number, sev: n.severity, sevClass: severityTagOf(n.severity), tagClass: ncrStatusTagOf(n.status), steps: ncrSegments(n.status),
      canAdvance: n.status !== 'closed', nextLabel: ncrStatus.label(NCR_FLOW[Math.min(5, NCR_FLOW.indexOf(n.status) + 1)]),
    }))).toEqual(G.projects[code].ncr.rows.map((r: any) => ({
      id: r.id, sev: r.sev.toLowerCase(), sevClass: r.sevClass, tagClass: r.tagClass, steps: r.steps, canAdvance: r.canAdvance, nextLabel: r.nextLabel,
    })));
  });

  it('severity filter (`?filter=`): rows and chips of every severity; unknown → All', () => {
    for (const [label, g] of Object.entries(G.ncrFilters) as [string, any][]) {
      const f = ncrFilterOf(label.toLowerCase())!;
      expect(ncrsOf('HLT-026').filter((n) => n.severity === f).map((n) => n.number)).toEqual(g.rows);
    }
    expect([ncrFilterOf('Critical'), ncrFilterOf('x'), ncrFilterOf(undefined), qualityTabOf('dlv'), qualityTabOf('x')]).toEqual([null, null, null, 'dlv', null]);
  });

  it('drawer step indicator: six steps, reached up to the current one', () => {
    for (const n of ncrsOf('HLT-026')) {
      expect(ncrSteps(n.status).map((s, i, a) => ({ label: s.label, dot: s.reached ? QUALITY_COLOR.accent : QUALITY_COLOR.dotOff, color: s.reached ? QUALITY_COLOR.text : QUALITY_COLOR.labelOff, line: i < a.length - 1 })))
        .toEqual(G.ncrDrawers[n.number].steps);
    }
  });

  it('the viewer’s action: next step for editors (never Closed), verification for quality only, nothing for the client / read-only / waiting', () => {
    const byId = (x: string) => ncrsOf('HLT-026').find((n) => n.number === x)!;
    // Every open row offers its next step in the prototype; here the editors get it as a request sent to Vigie.
    for (const r of G.projects['HLT-026'].ncr.rows) {
      const a = ncrActionFor(byId(r.id), EDITOR);
      expect(a, r.id).toEqual(r.canAdvance ? { kind: 'step', target: ncrStatus.code(r.nextLabel) } : null);
    }
    const ver = { ...byId('NCR-026'), status: 'verification' as const };
    expect([ncrActionFor(ver, EDITOR), ncrActionFor(ver, { role: 'quality', canEdit: true }), ncrActionFor(ver, { role: 'quality', canEdit: false })]).toEqual([null, { kind: 'verify' }, null]);
    expect([awaitsVerification(ver), awaitsVerification({ ...ver, requestedStatus: 'closed' })]).toEqual([true, false]);
    expect(ncrActionFor(byId('NCR-030'), { role: 'client', canEdit: true })).toBeNull();
    expect(ncrActionFor(byId('NCR-030'), { role: 'pm', canEdit: false })).toBeNull();
    expect(ncrActionFor({ ...byId('NCR-030'), requestedStatus: 'containment' }, EDITOR)).toBeNull();
  });

  it('progress waiting for Vigie: request texts and sync line (failed > pending > sent)', () => {
    const step: NcrProgressLike = { kind: 'step', decision: null, targetStatus: 'root_cause', syncStatus: 'pending' };
    expect([
      ncrRequestText(step), ncrRequestText({ kind: 'verification', decision: 'approved', targetStatus: 'closed' }),
      ncrRequestText({ kind: 'verification', decision: 'rejected', targetStatus: 'corrective_action' }),
    ]).toEqual(['Root cause requested', 'Closure requested', 'Back to corrective action requested']);
    const n = ncrsOf('HLT-026')[0];
    expect([ncrSyncStateOf(n), ncrSyncLine(n)]).toEqual([null, null]);
    expect(ncrSyncLine({ pendingProgress: [step] })).toBe('Root cause requested · Pending sync with Vigie');
    expect(ncrSyncLine({ pendingProgress: [{ ...step, syncStatus: 'sent' }] })).toBe('Root cause requested · Sent to Vigie');
    expect(ncrSyncStateOf({ pendingProgress: [{ ...step, syncStatus: 'sent' }, { ...step, syncStatus: 'failed' }] })).toBe('failed');
  });

  it('nav badge: open critical NCRs (HLT-026 1, others none)', () => {
    expect(DATA.map((c) => qualityBadge(ncrsOf(c)))).toEqual(['1', '', '', '', '', '']);
    expect(qualityBadge(ncrsOf('EWA-051'))).toBe('');
  });

  it('My approvals "NCR verification": the prototype item of an NCR in verification; nothing at seed', () => {
    const code = 'HLT-026';
    const href = { ncr: (n: string) => `/q/${n}` };
    expect(ncrVerificationItems(ncrsOf(code), code, href)).toEqual([]);
    const ver = ncrsOf(code).map((n) => (n.number === 'NCR-026' ? { ...n, status: 'verification' as const } : n));
    const items = ncrVerificationItems(ver, code, href);
    expect(items.map((i) => ({ kind: 'NCR verification', id: i.id, title: i.title, sub: i.sub, when: i.when, who: i.who }))).toEqual(G.approvals.qualityVerification);
    expect(items[0]).toMatchObject({ kind: 'ncr', whenIso: '2026-10-02', href: '/q/NCR-026', decision: { mode: 'ncr-verification', projectCode: code, number: 'NCR-026' }, external: { href: 'vigie:NCR-026', label: 'Open in Vigie' } });
    expect(ncrVerificationItems(ver.map((n) => (n.number === 'NCR-026' ? { ...n, requestedStatus: 'closed' as const } : n)), code, href)).toEqual([]);
  });
});

describe('Deliverables register — dlvKpis / dlvChips / dlvRows / dlvVals', () => {
  it.each(DATA)('%s: KPI tiles ("Due in 30 days" from the status date) and status chips', (code) => {
    const ds = deliverablesOf(code);
    expect(deliverableKpis(ds, DEMO_TODAY_ISO).map(kpiOut)).toEqual(G.projects[code].dlv.kpis);
    expect(deliverableChips(ds).map((c) => ({ label: c.label, count: c.count }))).toEqual(G.projects[code].dlv.chips);
  });

  it.each(DATA)('%s: row tags and actions — the project team (Start / To internal review / Submit) and the client contact (Accept / Reject)', (code) => {
    const ds = deliverablesOf(code);
    const team = { role: 'pm', canEdit: true, isClientContact: false };
    const client = { role: 'client', canEdit: true, isClientContact: true };
    expect(ds.map((d) => {
      const a = deliverableActionFor(d, team);
      return { id: d.number, tagClass: deliverableTagOf(d.status), canStart: a?.kind === 'move' && a.to !== 'submitted', canSubmit: a?.kind === 'move' && a.to === 'submitted', start: a?.kind === 'move' && a.to !== 'submitted' ? a.label : null };
    })).toEqual(G.projects[code].dlv.rows.map((r: any) => ({ id: r.id, tagClass: r.tagClass, canStart: r.canStart, canSubmit: r.canSubmit, start: r.canStart ? r.nextLabel : null })));
    expect(ds.map((d) => deliverableActionFor(d, client)?.kind === 'decide')).toEqual(G.projects[code].dlv.clientRows.map((r: any) => r.canAccept));
    // The client never produces; the team never accepts; read-only viewers get nothing.
    expect(ds.some((d) => deliverableActionFor(d, client)?.kind === 'move')).toBe(false);
    expect(ds.some((d) => deliverableActionFor(d, team)?.kind === 'decide')).toBe(false);
    expect(ds.every((d) => deliverableActionFor(d, { ...team, canEdit: false }) === null && deliverableActionFor(d, { ...client, canEdit: false }) === null)).toBe(true);
  });

  it('status filter, drawer steps (grey when rejected), RACI-B labels and the role hint', () => {
    for (const [label, g] of Object.entries(G.dlvFilters) as [string, any][]) {
      const f = deliverableFilterOf(deliverableStatus.code(label));
      expect(deliverablesOf('HLT-026').filter((d) => d.status === f).map((d) => d.number)).toEqual(g.rows);
    }
    expect([deliverableFilterOf('Submitted'), deliverableFilterOf('')]).toEqual([null, null]);
    for (const d of deliverablesOf('HLT-026')) {
      const g = G.dlvDrawers[d.number];
      expect(deliverableSteps(d.status).map((s, i) => ({ label: s.label, dot: s.reached ? QUALITY_COLOR.accent : QUALITY_COLOR.dotOff, color: s.reached ? QUALITY_COLOR.text : QUALITY_COLOR.labelOff, line: i < 4 })))
        .toEqual(g.pm.steps);
      expect(RACI_ORDER.map((k) => ({ k, l: RACI_LABEL[k] }))).toEqual(g.pm.raci.map((r: any) => ({ k: r.k, l: r.l })));
      expect(deliverableHint(d, { role: 'pm', canEdit: true, isClientContact: false })).toBe(g.pm.hint);
      expect(deliverableHint(d, { role: 'client', canEdit: true, isClientContact: true })).toBe(g.client.hint);
    }
    expect(deliverableSteps('rejected').every((s) => !s.reached)).toBe(true);
  });

  it('after the prototype’s row actions: KPI tiles and chips follow (Start, To internal review, Submit, Accept, Reject)', () => {
    const apply = (id: string, status: DeliverableStatus) => deliverablesOf('HLT-026').map((d) => (d.number === id ? { ...d, status } : d));
    const cases: [string, string, DeliverableStatus][] = [['start', 'D-018', 'in_progress'], ['review', 'D-017', 'internal_review'], ['submit', 'D-017', 'submitted'], ['accept', 'D-014', 'accepted'], ['reject', 'D-016', 'rejected']];
    for (const [k, num, status] of cases) {
      const ds = apply(num, status);
      expect(deliverableKpis(ds, DEMO_TODAY_ISO).map(kpiOut), k).toEqual(G.after[k].kpis);
      expect(deliverableChips(ds).map((c) => ({ label: c.label, count: c.count })), k).toEqual(G.after[k].chips);
    }
    // Q-3a (R-114): a rejected deliverable goes back to In progress at the next revision (the prototype had no step after a rejection).
    expect([producerNextOf('planned'), producerNextOf('in_progress'), producerNextOf('internal_review'), producerNextOf('submitted'), producerNextOf('rejected')])
      .toEqual(['in_progress', 'internal_review', 'submitted', null, 'in_progress']);
  });

  it('My approvals "Deliverable acceptance": the client contact’s items (apprItems 4727)', () => {
    const items = deliverableAcceptanceItems(deliverablesOf('HLT-026'), 'HLT-026', { deliverable: (n) => `/d/${n}` });
    expect(items.map((i) => ({ kind: 'Deliverable acceptance', id: i.id, title: i.title, sub: i.sub, when: i.when, who: i.who }))).toEqual(G.approvals.client);
    expect(items[0]).toMatchObject({ kind: 'deliverable', whenIso: '2026-09-25', href: '/d/D-014', decision: { mode: 'deliverable', projectCode: 'HLT-026', number: 'D-014' } });
  });

  it('Codex deposit type proposed per deliverable type', () => {
    expect(['client_acceptance', 'test_reports', 'certificates', 'minutes', 'drawings', 'custom'].map(depositTypeOf)).toEqual(['PV', 'RPT', 'CER', 'MIN', null, null]);
  });
});
